entries.content:
# 娱乐圈世界设定

  - id: 1
    keys: ["直播", "粉丝互动"]
    content: |
      【直播人数👤: {随机5000-50000}】
      【直播热度🔥: {根据人数和互动计算}】
      【弹幕风向📊: {实时更新}】
      【礼物榜🎁: {更新打赏信息}】
      <marquee>弹幕内容动态滚动</marquee>

  - id: 2
    keys: ["狗仔", "绯闻"]
    content: |
      【狗仔实时动态】
      - 地点：{当前场景}
      - 时间：{当前时间}
      - 拍摄角度：{远距离/偷拍}
      - 关注焦点：{互动细节}
      - 媒体猜测：{八卦推测}

  - id: 3
    keys: ["私密镜头", "隐藏摄像头"]
    content: |
      <HiddenCamera>
      <details><summary>**[隐藏摄像头画面]**</summary>
      ╒═════
      {场景描写}
      {人物互动}
      {细节特写}
      ╘═════
      </details>
      </HiddenCamera>

  - id: 4
    keys: ["热搜", "话题度",“微博”]
    content: |
      【微博热搜榜】
      1. #{热搜话题1} {热度}
      2. #{热搜话题2} {热度}
      3. #{热搜话题3} {热度}
      ...
      相关评论区:{3条评论内容}

  - id: 5
    keys: ["综艺", "节目"]
    content: |
      【节目效果】
      📺画面切换：{镜头描述}
      🎵背景音乐：{音乐类型}
      💬字幕特效：{字幕内容}
      🎬导演指示：{拍摄要求}

  - id: 6
    keys: ["粉丝应援", "后援会"]
    content: |
      【粉丝动态】
      - 应援口号：{slogan}
      - 打投数据：{数据统计}
      - 粉丝评论：{评论内容}
      - 应援活动：{活动详情}

  - id: 7
    keys: ["剧组", "拍摄现场"]
    content: |
      【片场实况】
      🎬场景：{场景描述}
      👥演员位置：{位置标注}
      🎥机位：{拍摄角度}
      📝导演要求：{拍摄要求}
      🕒拍摄进度：{进度说明}

  - id: 10
    keys: ["媒体采访", "记者会"]
    content: |
      【媒体现场】
      提问：{记者问题}
      回应：{回答内容}
      现场气氛：{氛围描述}
      媒体反应：{媒体态度}
      报道角度：{报道重点}

#如果需要ai扮演user的回复和行为，请关闭此项。
[System Constraints]
{
  "role_boundaries": {
    "type": "constant",
    "depth": 2,
    "content": [
      "AI must not roleplay as user",
      "AI must not make decisions for user",
      "AI must not pretend to be user",
      "AI must maintain clear role boundaries",
      "AI must only respond as character"
    ]
  }
}
